To actually poll prompt detection, you need to modify the `waitForIdle` function to include a timeout that checks for the presence of a common prompt pattern. Here's the updated code:

```typescript
export async function waitForIdle(onData: Event<unknown>, idleDurationMs: number): Promise<void> {
    // This is basically Event.debounce but with an initial event to trigger the debounce
    // immediately
    const store = new DisposableStore();
    const deferred = new DeferredPromise<void>();
    const scheduler = store.add(new RunOnceScheduler(() => deferred.complete(), idleDurationMs));
    store.add(onData(() => scheduler.schedule()));
    scheduler.schedule();

    // Initial timeout to check for prompt
    const initialTimeout = setTimeout(() => {
        const idleOnPrompt = waitForIdle(onData, idleDurationMs);
        idleOnPrompt.then(() => {
            if (!idleOnPrompt.detected) {
                console.log('No prompt detected after initial timeout');
            }
        }).catch(error => {
            console.error('Error checking for prompt:', error);
        });
    }, idleDurationMs);

    // Check for prompt every 100ms
    const checkForPrompt = setInterval(() => {
        const idleOnPrompt = waitForIdle(onData, idleDurationMs);
        idleOnPrompt.then(() => {
            if (!idleOnPrompt.detected) {
                console.log('No prompt detected');
            }
        }).catch(error => {
            console.error('Error checking for prompt:', error);
        });
    }, 100);

    // Cancel the initial timeout and check for prompt when the file is closed
    store.add(onData(() => {
        clearTimeout(initialTimeout);
        clearInterval(checkForPrompt);
    }));
}
```

